import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for batched matrix multiplication
batched_matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cublas_v2.h>

// Optimized batched matrix multiplication using cuBLAS
torch::Tensor batched_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // A: (N, M, K), B: (K, L) -> Output: (N, M, L)

    TORCH_CHECK(A.dim() == 3, "A must be 3D tensor");
    TORCH_CHECK(B.dim() == 2, "B must be 2D tensor");
    TORCH_CHECK(A.size(2) == B.size(0), "Inner dimensions must match");
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "Tensors must be on CUDA");
    TORCH_CHECK(A.is_contiguous() && B.is_contiguous(), "Tensors must be contiguous");

    const int N = A.size(0);
    const int M = A.size(1);
    const int K = A.size(2);
    const int L = B.size(1);

    auto output = torch::empty({N, M, L}, A.options());

    // Create cuBLAS handle
    cublasHandle_t handle;
    cublasCreate(&handle);

    const float alpha = 1.0f;
    const float beta = 0.0f;

    // For each batch, perform matrix multiplication
    // A[n] @ B = output[n]
    // A[n] is (M, K), B is (K, L), output[n] is (M, L)

    // cuBLAS uses column-major order, so we compute B^T @ A^T = (A @ B)^T
    // But since we want row-major result, we use the formula:
    // C = A @ B in row-major is equivalent to C^T = B^T @ A^T in column-major
    // So we compute: output = A @ B by calling cublasSgemm with swapped arguments

    for (int n = 0; n < N; n++) {
        const float* A_ptr = A.data_ptr<float>() + n * M * K;
        const float* B_ptr = B.data_ptr<float>();
        float* out_ptr = output.data_ptr<float>() + n * M * L;

        // For row-major matrices, to compute C = A @ B:
        // We call cublasSgemm(handle, CUBLAS_OP_N, CUBLAS_OP_N, L, M, K, &alpha, B, L, A, K, &beta, C, L)
        cublasSgemm(handle,
                    CUBLAS_OP_N, CUBLAS_OP_N,
                    L, M, K,
                    &alpha,
                    B_ptr, L,
                    A_ptr, K,
                    &beta,
                    out_ptr, L);
    }

    cublasDestroy(handle);

    return output;
}
"""

