import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for matrix-vector multiplication
matvec_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Kernel for matrix-vector multiplication with shared memory and warp reduction
// Each block computes one output element (one row of the matrix)
template <int BLOCK_SIZE>
__global__ void matvec_kernel(const float* __restrict__ A, 
                               const float* __restrict__ B, 
                               float* __restrict__ C, 
                               int M, int K) {
    int row = blockIdx.x;

    if (row >= M) return;

    // Each thread accumulates partial sum
    float sum = 0.0f;

    // Process elements in chunks
    for (int k = threadIdx.x; k < K; k += BLOCK_SIZE) {
        sum += A[row * K + k] * B[k];
    }

    // Warp-level reduction using shuffle
    #pragma unroll
    for (int offset = 16; offset > 0; offset /= 2) {
        sum += __shfl_down_sync(0xffffffff, sum, offset);
    }

    // Shared memory for inter-warp reduction
    __shared__ float shared[32];  // Max 32 warps per block

    int lane = threadIdx.x % 32;
    int warp_id = threadIdx.x / 32;

    if (lane == 0) {
        shared[warp_id] = sum;
    }
    __syncthreads();

    // Final reduction by first warp
    if (warp_id == 0) {
        int num_warps = (BLOCK_SIZE + 31) / 32;
        sum = (lane < num_warps) ? shared[lane] : 0.0f;

        #pragma unroll
        for (int offset = 16; offset > 0; offset /= 2) {
            sum += __shfl_down_sync(0xffffffff, sum, offset);
        }

        if (lane == 0) {
            C[row] = sum;
        }
    }
}

// Optimized kernel using vectorized loads (float4)
template <int BLOCK_SIZE>
__global__ void matvec_kernel_vectorized(const float* __restrict__ A, 
                                          const float* __restrict__ B, 
                                          float* __restrict__ C, 
                                          int M, int K) {
    int row = blockIdx.x;

    if (row >= M) return;

    float sum = 0.0f;

